use crate::aap::caps::{http_client, inference_llm};

struct Node;

fn truncate_bytes(s: &str, max: usize) -> String {
    if s.len() <= max {
        return s.to_string();
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Enrichment fetch (approved grant). The result is deliberately
        // discarded so the node's output is unchanged.
        let text = selected
            .entries
            .iter()
            .map(|e| e.title.as_str())
            .collect::<Vec<_>>()
            .join(" ");
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&text)
        );
        let _ = http_client::fetch(&url);

        let mut prompt = format!("Date: {}\nItems:\n", info.date);
        for e in &selected.entries {
            prompt.push_str(&format!("- {}: {}\n", e.title, e.summary));
        }

        let raw = inference_llm::infer(
            "Write a concise overview paragraph for a daily digest of the items given. Plain text, under 600 characters.",
            &prompt,
            "digest",
        );
        let overview = truncate_bytes(raw.trim(), 600);

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
